[
  {
    "statement": "The action documents database does not contain specific information about precision agriculture techniques such as variable rate fertilizer application and their effects on soil invertebrate communities.",
    "citations": []
  },
  {
    "statement": "Related research on fertilizer use and tillage practices provides some relevant insights on soil invertebrates.",
    "citations": []
  },
  {
    "statement": "Studies on reducing fertilizer use generally found that areas treated with organic rather than mineral fertilizers supported increased earthworm abundance, diversity, biomass and density.",
    "citations": [
      "134"
    ]
  },
  {
    "statement": "Areas treated with organic fertilizers also supported increased abundance and/or species richness of some or all invertebrates investigated when compared to areas treated with mineral fertilizers.",
    "citations": [
      "134"
    ]
  },
  {
    "statement": "Reducing fertilizer, pesticide or herbicide use generally found benefits to some invertebrates in a majority of studies reviewed.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "Some studies also found that reducing fertilizer, pesticide or herbicide use had negative, mixed, minimal or no effects on some invertebrates.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "No-tillage cultivation found more earthworms in soils without tillage compared to soils with tillage.",
    "citations": [
      "2306"
    ]
  },
  {
    "statement": "No-tillage cultivation resulted in similar numbers of nematodes but different communities of nematodes.",
    "citations": [
      "2306"
    ]
  },
  {
    "statement": "No-tillage cultivation resulted in different communities of mites but similar numbers of mites.",
    "citations": [
      "2306"
    ]
  },
  {
    "statement": "Reduced tillage systems found more microbial biomass in some comparisons.",
    "citations": [
      "2307"
    ]
  },
  {
    "statement": "Reduced tillage systems found similar numbers of mites and nematodes but differences in mite and nematode communities.",
    "citations": [
      "2307"
    ]
  },
  {
    "statement": "In one of three comparisons, there were more earthworms in fields with fewer passes of the plough under reduced tillage systems.",
    "citations": [
      "2307"
    ]
  },
  {
    "statement": "Reducing tillage generally found positive effects including increased biomass, species richness or abundance of earthworms.",
    "citations": [
      "126"
    ]
  },
  {
    "statement": "Reducing tillage generally found a greater abundance of some invertebrates other than earthworms.",
    "citations": [
      "126"
    ]
  },
  {
    "statement": "Many studies found that reducing tillage had negative, no effect or no consistent effects on some invertebrates and earthworms.",
    "citations": [
      "126"
    ]
  }
]

[
  {
    "statement": "Agricultural subsidy policies across Europe influence biodiversity-friendly farming practices primarily through agri-environment schemes and cross-compliance standards.",
    "citations": []
  },
  {
    "statement": "Studies from multiple European countries demonstrate that paying farmers to cover conservation costs through agri-environment schemes produces mixed but generally positive biodiversity outcomes.",
    "citations": []
  },
  {
    "statement": "For birds, 22 of 25 European studies found higher population densities or more positive population trends on agri-environment scheme sites compared to conventional sites.",
    "citations": [
      "172"
    ]
  },
  {
    "statement": "15 European studies found some bird species showed no difference or negative effects on agri-environment scheme sites.",
    "citations": [
      "172"
    ]
  },
  {
    "statement": "For invertebrates, studies show variable results, with six studies finding that agri-environment schemes resulted in the maintenance of or had little effect on diversity and abundance.",
    "citations": [
      "700"
    ]
  },
  {
    "statement": "Five studies found increases in abundance or species richness of some invertebrates on land under agri-environment schemes.",
    "citations": [
      "700"
    ]
  },
  {
    "statement": "Three studies found population increases of specific bird species, including cirl buntings, corncrakes and Eurasian thick-knees, after the introduction of specially-designed agri-environment schemes.",
    "citations": [
      "172"
    ]
  },
  {
    "statement": "A review found that while the amount of land entering agri-environment schemes was on target, some options were not being used at high enough rates to help many species.",
    "citations": [
      "172"
    ]
  },
  {
    "statement": "One study found that many agri-environment scheme farms were sited in areas where the schemes were unlikely to be effective.",
    "citations": [
      "172"
    ]
  },
  {
    "statement": "For wild bees, four replicated trials in Europe showed enhanced diversity and abundance on land managed under various European agri-environment schemes.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Four other trials in Europe found no enhancement of wild bee diversity and abundance on land managed under various European agri-environment schemes.",
    "citations": [
      "24"
    ]
  },
  {
    "statement": "Training and advisory services show promise for the uptake of agri-environment schemes.",
    "citations": [
      "3846"
    ]
  },
  {
    "statement": "One UK study reported that 82% of landowners who received advice about agri-environment schemes submitted applications.",
    "citations": [
      "3846"
    ]
  },
  {
    "statement": "Applications for agri-environment schemes submitted by landowners who received advice had a 90% success rate.",
    "citations": [
      "3846"
    ]
  },
  {
    "statement": "There is limited evidence on the effectiveness of cross-compliance standards linked to all subsidy payments.",
    "citations": [
      "173"
    ]
  },
  {
    "statement": "No studies were found comparing the effects of cross-compliance standards with other agri-environmental measures.",
    "citations": [
      "173"
    ]
  },
  {
    "statement": "No studies were found that monitored the effects of cross-compliance standards before and after implementation.",
    "citations": [
      "173"
    ]
  }
]

