  {
    "statement": "Creating beetle banks provides positive effects on invertebrate densities and numbers.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "Creating beetle banks has positive effects on invertebrate distribution.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "Creating beetle banks leads to higher ground beetle density and species diversity in spring and summer.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "Creating uncultivated margins around intensive arable or pasture fields supports more invertebrates than conventionally managed field margins.",
    "citations": [
      "63"
    ]
  },
  {
    "statement": "Uncultivated margins around intensive arable or pasture fields support more invertebrates than other field margin options.",
    "citations": [
      "63"
    ]
  },
  {
    "statement": "Naturally regenerated margins show an increased abundance or biomass of species.",
    "citations": [
      "63"
    ]
  },
  {
    "statement": "Leaving cultivated, uncropped margins or plots can increase the species richness and abundance of spiders.",
    "citations": [
      "562"
    ]
  },
  {
    "statement": "Leaving cultivated, uncropped margins or plots increases the abundance of ground-dwelling invertebrates and ground beetles.",
    "citations": [
      "562"
    ]
  },
  {
    "statement": "Leaving cultivated, uncropped margins or plots increases the species richness of bumblebees.",
    "citations": [
      "562"
    ]
  },
  {
    "statement": "Undersowing spring cereals with clover benefits arthropod abundance and species richness.",
    "citations": [
      "136"
    ]
  },
  {
    "statement": "Undersowing spring cereals with clover increases bumblebee, butterfly, ground beetle, spider and springtail abundances.",
    "citations": [
      "136"
    ]
  },
  {
    "statement": "Converting to organic farming shows greater species richness and abundance of butterflies, burnet moths, and all moths than conventionally managed farms.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "Converting to organic farming may involve higher conversion costs compared to margin-based approaches.",
    "citations": []
  }
]

[
  {
    "statement": "No specific studies were found that directly compare GPS-guided variable rate fertilizer application to standard application methods and their effects on soil invertebrate populations.",
    "citations": []
  },
  {
    "statement": "Several relevant findings about fertilizer application methods and the impacts of these methods on soil invertebrates are available.",
    "citations": []
  },
  {
    "statement": "Reducing fertilizer applications had positive effects on invertebrates in five studies.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "Four studies found no or no consistent effects on some invertebrates from reducing fertilizer applications.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "Plots where fertilizer inputs were not reduced tended to have higher earthworm biomass or abundance.",
    "citations": [
      "139"
    ]
  },
  {
    "statement": "Areas treated with organic rather than mineral fertilizers supported increased earthworm abundance, diversity, biomass and density.",
    "citations": [
      "134"
    ]
  },
  {
    "statement": "Areas treated with organic rather than mineral fertilizers supported increased abundance and/or species richness of some or all invertebrates investigated in fourteen studies.",
    "citations": [
      "134"
    ]
  },
  {
    "statement": "A literature review found organic fertilizers without pesticides produced the highest earthworm biomass.",
    "citations": [
      "134"
    ]
  },
  {
    "statement": "One study showed fewer nematodes and fewer mites in plots with organic fertilizer compared to inorganic fertilizer.",
    "citations": [
      "1366"
    ]
  },
  {
    "statement": "Another study found fewer bacteria in soils with organic fertilizer.",
    "citations": [
      "1366"
    ]
  },
  {
    "statement": "Densities of some invertebrates were higher in unfertilized plots compared with plots receiving nitrogen inputs.",
    "citations": [
      "694"
    ]
  },
  {
    "statement": "A separate study found lower invertebrate abundance on plots with reduced fertilizer inputs, but the differences were not significant.",
    "citations": [
      "694"
    ]
  }
]
